# Figure 6 (spec: 00_meta/figure6_spec_v1.md): lesion axis. A-C two Visium slides (H&E | manual grade | GIScore), D-F spot-level boxplots (+slide means), G all-gene trend,
# H-J Elhossiny epithelial pseudobulk (class boxplots, GL/PD pairs, depth caveat).
suppressPackageStartupMessages({library(data.table); library(ggplot2); library(patchwork); library(png); library(ggbeeswarm); library(ggrepel)})
root <- "${PROJECT_ROOT}"; r6 <- file.path(root, "04_results/2026-10-12_Figure6_GALNT_run01"); out <- file.path(root, "05_figures/2026-10-12_Figure6_GALNT_run01"); dir.create(out, recursive = TRUE, showWarnings = FALSE)
fam <- "Arial"; set.seed(666)
theme_pub <- function(bs = 6) theme_classic(base_size = bs, base_family = fam) + theme(axis.line = element_line(linewidth = 0.25), axis.ticks = element_line(linewidth = 0.25), plot.title = element_text(size = bs + 0.5, face = "bold"), legend.key.size = unit(2.6, "mm"), legend.title = element_text(size = bs), legend.text = element_text(size = bs - 0.5), plot.margin = margin(2, 3, 2, 2))
gcol <- c(normal = "#8FA3B5", low_grade = "#E3B23C", high_grade = "#C9453B"); glab <- c(normal = "Normal", low_grade = "Low grade", high_grade = "High grade")
pfmt <- function(p) ifelse(p < 0.001, formatC(p, format = "e", digits = 1), formatC(p, format = "f", digits = 3))
mp <- fread(file.path(r6, "H1_all_spots_map.csv")); sp <- fread(file.path(r6, "H1_spots_used.csv")); sp[, grade := factor(grade, levels = names(gcol))]
## slides pre-fixed by rule (not by outcome): the slide with all three grades (HG2) and the slide with most high-grade spots (HG4)
slides <- c("PanIN-HG2", "PanIN-HG4"); nm <- c("PanIN-HG2" = "Slide 7 (HG2)", "PanIN-HG4" = "Slide 4 (HG4)")
slide_panels <- function(s, tagrow) {
  d <- mp[sample == s]; sf <- jsonlite::fromJSON(file.path(root, "02_intermediate/fig6_visium", s, "scalefactors_json.json")); sc <- sf$tissue_hires_scalef; ps <- sf$spot_diameter_fullres * sc
  img <- readPNG(file.path(root, "02_intermediate/fig6_visium", s, "tissue_hires_image.png")); H <- dim(img)[1]; W <- dim(img)[2]
  d[, `:=`(x = px_col * sc, y = px_row * sc)]; pad <- 25; xl <- c(min(d$x) - pad, max(d$x) + pad); yl <- c(max(d$y) + pad, min(d$y) - pad)
  base <- function() ggplot() + annotation_raster(img, 0, W, -H, 0, interpolate = TRUE) + scale_x_continuous(limits = xl, expand = c(0, 0)) + scale_y_continuous(limits = -yl, expand = c(0, 0)) + coord_fixed() + theme_void(base_family = fam) + theme(plot.margin = margin(1, 1, 1, 1))
  d[, yy := -y]; epi <- d[paningrade %in% names(gcol)]; epi[, grade := factor(paningrade, levels = names(gcol))]
  pa <- base() + labs(title = if (tagrow == 1) "H&E" else NULL, y = nm[s]) + theme(axis.title.y = element_text(size = 5.5, angle = 90, face = "bold"), plot.title = element_text(size = 6.5, face = "bold", hjust = 0.5))
  pb <- base() + geom_point(data = epi, aes(x, yy, colour = grade), size = 0.8, shape = 16) + geom_point(data = data.frame(x = NA_real_, yy = NA_real_, grade = factor(names(gcol), levels = names(gcol))), aes(x, yy, colour = grade), na.rm = TRUE) + scale_colour_manual(values = gcol, labels = c(normal = "Normal", low_grade = "LG", high_grade = "HG"), name = NULL, drop = FALSE) + labs(title = if (tagrow == 1) "Manual grade" else NULL) + theme(plot.title = element_text(size = 6.5, face = "bold", hjust = 0.5), legend.position = if (tagrow == 2) "bottom" else "none", legend.text = element_text(size = 5), legend.key.size = unit(2.2, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(0.5, "mm")) + guides(colour = guide_legend(nrow = 1, override.aes = list(size = 1.6)))
  pc <- base() + geom_point(data = epi, aes(x, yy, colour = GIScore), size = 0.8, shape = 16) + scale_colour_gradient2(low = "#2E6FB7", mid = "grey85", high = "#C9453B", midpoint = 0, limits = c(-1.5, 1.5), oob = scales::squish, name = NULL) + labs(title = if (tagrow == 1) "GIScore (spots)" else NULL) + theme(plot.title = element_text(size = 6.5, face = "bold", hjust = 0.5), legend.position = if (tagrow == 2) "bottom" else "none", legend.text = element_text(size = 5.5), legend.key.width = unit(6, "mm"), legend.key.height = unit(1.8, "mm"), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(0.5, "mm")) + guides(colour = guide_colourbar(ticks.linewidth = 0.2))
  list(pa, pb, pc)
}
S1 <- slide_panels(slides[1], 1); S2 <- slide_panels(slides[2], 2)
S1[[1]] <- S1[[1]] + labs(tag = "A") + theme(plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
for (i_ in 2:3) S1[[i_]] <- S1[[i_]] + labs(tag = c("B", "C")[i_ - 1]) + theme(plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
## D-F boxplots by grade, with slide means
tr <- fread(file.path(r6, "H1_trend_mixed_model.csv"))[model == "primary: ~grade + (1|slide)"]; sm <- fread(file.path(r6, "H1_slide_means.csv")); sm[, grade := factor(grade, levels = names(gcol))]
ng <- sp[, .N, by = grade][order(grade)]; xl_ <- paste0(c("Normal", "LG", "HG"), "\n(n = ", ng$N, ")")
vio <- function(m, lab, tag) ggplot(sp, aes(grade, .data[[m]])) + geom_violin(aes(fill = grade), scale = "width", width = 0.8, linewidth = 0.2, colour = "grey30", alpha = 0.45, bw = if (m == "GIScore") 0.15 else 0.05) + geom_line(data = sm, aes(grade, .data[[m]], group = sample), colour = "grey35", linewidth = 0.25) + geom_point(data = sm, aes(grade, .data[[m]]), size = 1.1, shape = 21, fill = "white", stroke = 0.35) +
  scale_fill_manual(values = gcol, guide = "none") + scale_x_discrete(labels = xl_) + labs(x = NULL, y = lab, title = sprintf("slope/grade = %.3f, p = %s", tr[metric == m]$beta_per_grade, pfmt(tr[metric == m]$p)), tag = tag) + theme_pub() + theme(plot.title = element_text(size = 5.2, face = "plain"), axis.text.x = element_text(size = 5.2), plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
sD <- vio("GALNT16", "GALNT16 (log1p CP10k)", "A"); sE <- vio("GALNT14", "GALNT14 (log1p CP10k)", "B"); sF <- vio("GIScore", "GIScore (z, epithelial spots)", "C")
## G all-gene trend (Visium)
gt <- fread(file.path(r6, "H1_all_gene_trend.csv")); gt <- gt[!is.na(p)]; gt[, lo := beta_per_grade - 1.96 * se]; gt[, hi := beta_per_grade + 1.96 * se]; gt[, sig := BH < 0.05]; gt[, gene := factor(gene, levels = gt[order(beta_per_grade)]$gene)]
pG <- ggplot(gt, aes(beta_per_grade, gene)) + geom_vline(xintercept = 0, linetype = 2, linewidth = 0.25, colour = "grey50") + geom_errorbar(aes(xmin = lo, xmax = hi, colour = sig), orientation = "y", width = 0, linewidth = 0.3) + geom_point(aes(colour = sig), size = 1) + scale_colour_manual(values = c("TRUE" = "#C9453B", "FALSE" = "grey55"), labels = c("TRUE" = "BH < 0.05", "FALSE" = "n.s."), name = NULL) +
  labs(x = "Mixed-model slope per grade step (normal-LG-HG)", y = NULL, title = "All GALNT-system genes (exploratory)", tag = "D") + theme_pub() + theme(axis.text.y = element_text(size = 4.8), legend.position = "bottom", legend.margin = margin(0, 0, 0, 0), plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
## H: six PanIN-associated enzymes, slide means per grade (exploratory; robustness table H1_panin_enzymes_robustness.csv)
rb <- fread(file.path(r6, "H1_panin_enzymes_robustness.csv")); enz <- c("GALNT3", "GALNT6", "GALNT4", "GALNT5", "GALNT10", "C1GALT1")
allsp <- fread(file.path(root, "02_intermediate/fig6_visium/spots_galnt_annot.csv.gz")); allsp <- allsp[paningrade %in% names(gcol) & lib >= 500 & nontissue < 100]; allsp[, grade := factor(paningrade, levels = names(gcol))]
sl6 <- melt(allsp[, c("sample", "grade", enz), with = FALSE], id.vars = c("sample", "grade"), variable.name = "gene", value.name = "v")[, .(v = mean(v), n = .N), by = .(sample, grade, gene)]
lab6 <- rb[, .(gene = factor(gene, levels = enz), t = sprintf("slope %.2f, p = %s\n(adj. p = %s)", beta, pfmt(p), pfmt(p_adj)))]; sl6[, gene := factor(gene, levels = enz)]
pH6 <- ggplot(sl6, aes(grade, v)) + geom_line(aes(group = sample), colour = "grey55", linewidth = 0.25) + geom_point(aes(fill = grade, size = n), shape = 21, stroke = 0.25) + geom_text(data = lab6, aes(x = 2, y = Inf, label = t), vjust = 1.15, size = 4.2 / .pt, family = fam, lineheight = 0.9, inherit.aes = FALSE) + facet_wrap(~gene, scales = "free_y", nrow = 2) + scale_y_continuous(expand = expansion(mult = c(0.05, 0.4))) +
  scale_fill_manual(values = gcol, guide = "none") + scale_size(range = c(0.6, 2.4), breaks = c(10, 50, 100), name = "Spots") + scale_x_discrete(labels = c("N", "LG", "HG")) + labs(x = NULL, y = "Slide mean (log1p CP10k)", title = "PanIN-associated enzymes (one line per slide)", tag = "E") + theme_pub() + theme(strip.background = element_blank(), strip.text = element_text(size = 5.5, face = "bold"), legend.position = "bottom", legend.key.size = unit(2, "mm"), legend.margin = margin(0, 0, 0, 0), plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
## I-K Elhossiny
E <- fread(file.path(r6, "H2_epithelial_pseudobulk_scores.csv")); E[, cls := factor(cls, levels = c("Donor_PanIN", "AdjNormal_PanIN", "GLTumor", "PDTumor"), labels = c("Donor", "Adj. normal", "GL tumor", "PD tumor"))]
h2 <- fread(file.path(r6, "H2_trend.csv")); ccol <- c("Donor" = "#8FA3B5", "Adj. normal" = "#A9C5A0", "GL tumor" = "#E3B23C", "PD tumor" = "#C9453B")
El <- melt(E, id.vars = c("unit", "cls", "patient_or_donor_Id"), measure.vars = c("GALNT16", "GALNT14", "GIScore"), variable.name = "metric", value.name = "v"); El[, metric := factor(metric, levels = c("GALNT16", "GALNT14", "GIScore"), labels = c("GALNT16 (log1p CPM)", "GALNT14 (log1p CPM)", "GIScore (z)"))]
lab <- h2[, .(metric = factor(metric, levels = c("GALNT16", "GALNT14", "GIScore"), labels = levels(El$metric)), t = sprintf("rho = %.2f, p = %s", rho, pfmt(p_jt)))]
pH <- ggplot(El, aes(cls, v)) + geom_boxplot(aes(fill = cls), width = 0.6, outlier.shape = NA, linewidth = 0.25, alpha = 0.55) + geom_quasirandom(size = 0.8, width = 0.15) + geom_text(data = lab, aes(x = 2.5, y = Inf, label = t), vjust = 1.4, size = 4.6 / .pt, family = fam, inherit.aes = FALSE) + facet_wrap(~metric, scales = "free_y", nrow = 1) + scale_y_continuous(expand = expansion(mult = c(0.05, 0.3))) + scale_fill_manual(values = ccol, guide = "none") + labs(x = NULL, y = NULL, title = "Epithelial pseudobulk, Elhossiny Visium (Jonckheere trend)", tag = "F") + theme_pub() + theme(axis.text.x = element_text(angle = 40, hjust = 1, size = 5), strip.background = element_blank(), strip.text = element_text(size = 5.5, face = "bold"), plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
pp <- fread(file.path(r6, "H2_GL_vs_PD_paired.csv"))
pr <- E[cls %in% c("GL tumor", "PD tumor")]; pr[, pat := patient_or_donor_Id]
pI <- ggplot(pr, aes(cls, GIScore, group = sample_Id)) + geom_line(colour = "grey50", linewidth = 0.3) + geom_point(aes(colour = cls), size = 1.3) + scale_colour_manual(values = ccol, guide = "none") + labs(x = NULL, y = "GIScore (z)", title = "GL vs PD tumour (paired)", subtitle = sprintf("GIScore, n = %d pairs, p = %s", pp[metric == "GIScore"]$n_pairs, pfmt(pp[metric == "GIScore"]$p_signed_rank)), tag = "G") + theme_pub() + theme(plot.subtitle = element_text(size = 5, colour = "grey25"), plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1))
pJ <- ggplot(E, aes(libsize / 1e6, c16 + 1, colour = cls)) + geom_point(size = 1.4) + scale_x_log10() + scale_y_log10() + scale_colour_manual(values = ccol, name = NULL) + labs(x = "Epithelial counts per pseudobulk (millions)", y = "GALNT16 counts + 1", title = "Depth caveat", tag = "H") + theme_pub() + theme(legend.position = "bottom", legend.text = element_text(size = 4.8), legend.key.size = unit(2, "mm"), legend.margin = margin(0, 0, 0, 0), plot.tag = element_text(size = 10, face = "bold", family = fam), plot.tag.position = c(0, 1)) + guides(colour = guide_legend(nrow = 1))
## assemble
lgB <- cowplot::get_plot_component(S2[[2]], "guide-box-bottom", return_all = FALSE); lgC <- cowplot::get_plot_component(S2[[3]], "guide-box-bottom", return_all = FALSE)
S2[[2]] <- S2[[2]] + theme(legend.position = "none"); S2[[3]] <- S2[[3]] + theme(legend.position = "none")
left <- wrap_plots(S1[[1]], S1[[2]], S1[[3]], S2[[1]], S2[[2]], S2[[3]], plot_spacer(), wrap_elements(full = lgB), wrap_elements(full = lgC), design = "ABC\nDEF\nGHI", heights = c(1, 1.14, 0.2))  # legends in their own row keep both slide rows column-aligned
top <- left
mid <- wrap_plots(pG, pH6, nrow = 1, widths = c(2.3, 4.9))
bot <- wrap_plots(pH, wrap_plots(pI, pJ, nrow = 1, widths = c(1, 1.15)), ncol = 1, heights = c(1.1, 1))
rws <- lapply(list(top, mid, bot), function(r) wrap_elements(full = r))  # rows do not share gutters
comp <- wrap_plots(rws, ncol = 1, heights = c(4.3, 2.8, 2.8)) & theme(text = element_text(family = fam))
W <- 7.2; Hh <- 9.9
ggsave(file.path(out, "Figure6.svg"), comp, width = W, height = Hh, device = svglite::svglite); ggsave(file.path(out, "Figure6.png"), comp, width = W, height = Hh, dpi = 400, device = ragg::agg_png); ggsave(file.path(out, "Figure6.tiff"), comp, width = W, height = Hh, dpi = 600, device = ragg::agg_tiff, compression = "lzw")
S6 <- wrap_plots(sD, sE, sF, nrow = 1) & theme(text = element_text(family = fam))
ggsave(file.path(out, "FigureS6_spot_level_by_grade.svg"), S6, width = 7.2, height = 2.7, device = svglite::svglite); ggsave(file.path(out, "FigureS6_spot_level_by_grade.png"), S6, width = 7.2, height = 2.7, dpi = 300, device = ragg::agg_png)
cat("done\n")
